mapper.select:

WHERE CLASS_CODE = #{classCode}
  AND TYPE = #{imageType}
ORDER BY SORT_ORDER, CLASS_IMG_CODE

mapper.delete:
DELETE FROM CLASS_IMG
WHERE CLASS_CODE = #{classCode}
  AND TYPE = #{imageType}

mapper.insert:

	SELECT (SELECT NVL(MAX(CLASS_IMG_CODE), 0) FROM CLASS_IMG)
		+ SEQ_CLASS_IMG_CODE.NEXTVAL
	FROM DUAL

INSERT INTO CLASS_IMG (
	CLASS_IMG_CODE, CLASS_CODE, TYPE, IMAGE, SORT_ORDER
) VALUES (
	#{imageCode}, #{classCode}, #{imageType}, #{imagePath}, #{imageOrder}
)
